package gg.hera.features;
import org.junit.jupiter.api.Test;
import net.minecraft.util.math.Vec3d;
import static org.junit.jupiter.api.Assertions.*;
class CameraQualityTest {
 @Test void freecamSamplesIntermediateFramesWithoutAdvancingSimulation(){var path=new CameraPath();path.reset(new Vec3d(10,20,30));path.beginTick();path.move(new Vec3d(4,2,-2));assertEquals(new Vec3d(10,20,30),path.sample(0));assertEquals(new Vec3d(12,21,29),path.sample(.5f));assertEquals(new Vec3d(14,22,28),path.sample(1));assertEquals(new Vec3d(11,20.5,29.5),path.sample(.25f));}
 @Test void menusAndStopsDoNotReplayTheLastMovement(){var path=new CameraPath();path.reset(Vec3d.ZERO);path.beginTick();path.move(new Vec3d(1,0,0));path.beginTick();assertEquals(new Vec3d(1,0,0),path.sample(0));assertEquals(new Vec3d(1,0,0),path.sample(.5f));path.reset(new Vec3d(100,0,0));assertEquals(new Vec3d(100,0,0),path.sample(0));assertEquals(new Vec3d(100,0,0),path.sample(1));}
 @Test void sessionResetsOnRespawnDimensionChangeDeathAndDisconnect(){var session=new CameraSession();Object world=new Object(),player=new Object();assertTrue(session.update(world,player,true));assertFalse(session.update(world,player,true));assertTrue(session.matches(world,player));assertFalse(session.matches(new Object(),player));assertFalse(session.matches(world,new Object()));player=new Object();assertTrue(session.update(world,player,true));assertFalse(session.update(world,player,true));assertTrue(session.update(world,player,false));assertTrue(session.update(new Object(),player,true));assertTrue(session.update(null,null,false));assertFalse(session.matches(null,null));}
 @Test void zoomEasingIsFrameRateIndependentAndReleases(){var a=new ZoomTransition();var b=new ZoomTransition();a.sample(false,true,0);b.sample(false,true,0);float av=0,bv=0;for(int i=1;i<=20;i++)av=a.sample(true,true,i*10_000_000L);for(int i=1;i<=4;i++)bv=b.sample(true,true,i*50_000_000L);assertEquals(av,bv,.00001);assertTrue(av>.98f&&av<1);assertTrue(a.sample(false,true,250_000_000L)<av);a.reset();assertEquals(0,a.sample(false,true,300_000_000L));}
 @Test void instantZoomAndNonMonotonicSamplingStayBounded(){var zoom=new ZoomTransition();assertEquals(1,zoom.sample(true,false,50));assertEquals(0,zoom.sample(false,false,100));assertEquals(0,zoom.sample(true,true,0));assertEquals(1,zoom.sample(true,false,500));zoom.reset();assertEquals(0,zoom.sample(true,true,100));}
}
